// Visible Session Volume Value Break Model
// Volume-profile-at-price engine: POC + value-area expansion, breakout signals.
// ATR: not used. CCI/ADX: not used. Math audited: proportional overlap split,
// expand-from-POC to 70% target, stepline levels, Wilder-free pure profile.

rows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
useVisible = input(true, "Session Mode Visible Chart")
extendLines = input(true, "Extend POC/VAH/VAL")
showFill = input(true, "Show Value Fill")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range (120-bar visible proxy, 60-bar compact mode) ──
sessLen = 120
if not useVisible {
    sessLen := 60
}
hh = highest(high, 120)
ll = lowest(low, 120)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / rows
if binH <= 0 {
    binH := close * 0.001
}

// ─── Fresh volume-at-price bins rebuilt every bar ─────────────────────
binVol = array()
i = 0
while i < rows {
    array.push(binVol, 0.0)
    i := i + 1
}
b = 0
while b < sessLen {
    bh = high[b]
    bl = low[b]
    bv = volume[b]
    barRng = bh - bl
    if barRng <= 0 {
        barRng := binH
        bh := bl + barRng
    }
    k = 0
    while k < rows {
        binLow = ll + k * binH
        binTop = binLow + binH
        top = bh
        if binTop < top {
            top := binTop
        }
        bot = bl
        if binLow > bot {
            bot := binLow
        }
        ov = top - bot
        if ov > 0 {
            share = ov / barRng
            if share > 1 {
                share := 1
            }
            array.set(binVol, k, array.get(binVol, k) + bv * share)
        }
        k := k + 1
    }
    b := b + 1
}
totalVol = array.sum(binVol)
if totalVol <= 0 {
    totalVol := 1
}

// ─── Point of control: max node volume bin ───────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
j = 1
while j < rows {
    v = array.get(binVol, j)
    if v > pocVal {
        pocVal := v
        pocBin := j
    }
    j := j + 1
}
pocPrice = ll + (pocBin + 0.5) * binH
pocShare = pocVal / totalVol

// ─── Value area: expand from POC adding higher-volume neighbor ───────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal < 0 and leftVal < 0 {
        guard := rows
    } else {
        if rightVal >= leftVal and vaHigh < rows - 1 {
            vaHigh := vaHigh + 1
            accum := accum + rightVal
        } else {
            if vaLow > 0 {
                vaLow := vaLow - 1
                accum := accum + leftVal
            } else {
                if vaHigh < rows - 1 {
                    vaHigh := vaHigh + 1
                    accum := accum + rightVal
                }
            }
        }
        guard := guard + 1
    }
}
vahPrice = ll + (vaHigh + 1) * binH
valPrice = ll + vaLow * binH
vaHeight = vahPrice - valPrice
insideVA = close >= valPrice and close <= vahPrice

// ─── Terrain height: POC price lifted by POC dominance (price-denominated) ─
terrainSrc = pocPrice + pocShare * rng
vaTopSrc = vahPrice + pocShare * rng * 0.5

// ─── Signals: close leaving value ────────────────────────────────────
prevClose = close[1]
prevVah = vahPrice[1]
prevVal = valPrice[1]
buySig = close > vahPrice and prevClose <= prevVah
sellSig = close < valPrice and prevClose >= prevVal

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
    model.longEntry("VBreakUp", 1)
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
    model.shortEntry("VBreakDn", 1)
}

// ─── POC rail label: only on newly established POC bin ───────────────
var wasPocBin = -1
if pocBin != wasPocBin {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}
wasPocBin := pocBin

// ─── 2D: same POC/VAH/VAL + profile shape when 3D is off ─────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(terrainSrc, "Value Height", "#4488ff", 1)
plot(pocShare * 100, "POC Share %", "#b48cff", 1, "separate")
plot(vaHeight, "VA Height", "#22cc88", 1, "separate")
if showFill {
    fill(vahPrice, valPrice, "rgba(68,136,255,0.12)")
}
if not insideVA {
    bgcolor("rgba(255,136,0,0.06)")
}

// ─── 3D: value terrain + POC labelled rail (same pane, distinct depths) ─
plot3d(terrainSrc, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputes every bar.
// FIX 2: close[-1] is a future leak -> close > lvl uses the current confirmed close.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine -> Oak positional (bar_index, price, title, style, color).
// FIX 4: RSI surface in pane="3d" is a spiky forest over price -> pane="separate" per PANE LAW.
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0, 0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", 1.0, 0, "separate")
}
plot(lvl, "High 20", "#ffcc44", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")
